      SUBROUTINE PARADECC     PRINTS FITTED VALUES OF VARIED PARAMETERSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'RDCHAR.CIN'CC     LOCAL VARIABLESC      CHARACTER*8     LABOUT      EXTERNAL        DATAR, IDATAC------------------------------------------------------------------C      NUM = 1      NDIF = 1C    1 I = ISTOR(NUM)      TYPE = IDATA(I)C      IF (TYPE .NE. 30) GO TO 5100      LABOUT(2:7) = LABEL(NUM)(1:6)      IF (LABEL(NUM) .EQ. BLANK) THEN        LABOUT(1:1) = BLANK        LABOUT(8:8) = BLANK      ELSE        LABOUT(1:1) = QUOTE        LABOUT(8:8) = QUOTE      ENDIFCC     DO VARY CODESC   30 IVA = 0      ISIG = TIE(I+1)      IF (ISIG .GE. 99) ISIG = 0      IF (ISIG .NE. 0 .AND. ISIG .NE. 100) IVA = 1   60 IF (IVA .EQ. 0) GO TO 5100CC     30. -- PARAMETERC      IF (LABEL(NUM) .EQ. BLANK) GO TO 5100      IF (.NOT. SUPP) THEN        PARAM = DATAR(I+1)        WRITE (NOUT,9300) NUM, LABOUT, PARAM      ENDIF      GO TO 5000CC     PRINT VARY CODESC 5000 IF (IVA .NE. 0) WRITE (NOUT,9500)C 5100 NUM = NUM + NDIF      IF (NUM .LE. NEL) GO TO 1CC     RETURNC 5200 RETURNC 9300 FORMAT (2H (,I4,')',2X,'*PARAM*',8X,A8,4X,E16.8) 9500 FORMAT (1H ,12X,'VARIED ')      END